import unittest
from candidate import monotonic

class TestMonotonic(unittest.TestCase):
    def test_monotonic_increasing(self):
        self.assertTrue(monotonic([1, 2, 4, 20]))

    def test_monotonic_decreasing(self):
        self.assertTrue(monotonic([4, 1, 0, -10]))

    def test_monotonic_mixed(self):
        self.assertFalse(monotonic([1, 20, 4, 10]))

    def test_monotonic_empty_list(self):
        self.assertTrue(monotonic([]))

    def test_monotonic_single_element(self):
        self.assertTrue(monotonic([1]))

    def test_monotonic_duplicate_element(self):
        self.assertTrue(monotonic([1, 1]))

    def test_monotonic_sorted_list(self):
        self.assertTrue(monotonic(sorted([1, 2, 3])))
        self.assertTrue(monotonic(sorted([1, 2, 3], reverse=True)))

    def test_monotonic_reversed_sorted_list(self):
        self.assertFalse(monotonic(sorted([1, 3, 2])))
        self.assertFalse(monotonic(sorted([3, 2, 1], reverse=True)))

    def test_monotonic_negative_numbers(self):
        self.assertTrue(monotonic([-4, -1, 0, -10]))

    def test_monotonic_non_numeric_elements(self):
        self.assertFalse(monotonic([1, 'a', 3]))
